function Social:InitialDatabase()
    local dbPath = DB_PATH
    if not File.Exists(dbPath) then
        Directory.CreateDirectory(MSG_BASE_PATH)
    end
    if not File.Exists(dbPath) then
        File.WriteAllBytes(dbPath, ResourceModule.LoadSyncFromStreamingAssets(DB_NAME))
    end
    if File.Exists(dbPath) then
        local db = sqlite3.open(dbPath)
        if db and db:isopen() then
            --先判断新的数据是否存在
            for row in db:nrows("SELECT count(*) size FROM sqlite_master WHERE type='table' AND name='message_remind2'") do
                if row.size <= 0 then
                    --不存在建立
                    db:exec([[
CREATE TABLE `message_remind2` (
    `id`              INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    `playerId`	      INTEGER NOT NULL,
    `newMessage`	  TEXT,
    `lastReceiveTime` INTEGER,
    `lastReadTime`	  INTEGER,
    `hasNewMessage`   INTEGER,
    `myPlayerId`	  INTEGER,
    `ext1` TEXT
);
                        ]])
                end
            end

            for row in db:nrows("SELECT count(*) size FROM sqlite_master WHERE type='table' AND name='oversea_group_msg'") do
                if row.size <= 0 then
                    --不存在建立
                    db:exec([[
CREATE TABLE "oversea_group_msg" (
    "id"              INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "userId"          INTEGER,
    "playerId"	      INTEGER NOT NULL,
    "name"	          TEXT,
    "level"           INTEGER,
    "avatar"          INTEGER,
    "avatarFrame"     INTEGER,
    "message"         TEXT,
    "sendTime"        INTEGER,
    "chatChannel"     INTEGER,
    "msgType"         INTEGER,
    "exParam1"        INTEGER,
    "exParam2"        TEXT,
    "exParam3"        TEXT
);
                        ]])
                end
            end
            db:close()

        else
            error("the database file not exists")
        end
    end
    ---@type PlayerComponent
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComp then
        self.playerId = checkNumber(playerComp.playerDojo.playerId)
    end
    if not isInitialized then
        self:ClearHandlers()
        local instance = self:GetSocialRelayGameObject()
        if instance then
            if not GameUtils.isZmFunction() then
                -----@type GVoice.GVoiceEngineHelper
