function Social:StartRecording(filePath)
    local canRecording = true
    if KTool.UNITY_ANDROID() and not KTool.UNITY_EDITOR() then
        local AndroidRuntimePermissions = CS.AndroidRuntimePermissions
        ---权限申请
        if not AndroidRuntimePermissions.CheckPermission(ANDROID_PERMISSION) then
            ---没有权限的情况下
            local permission = AndroidRuntimePermissions.RequestPermission(ANDROID_PERMISSION)
            if permission ~= CS.AndroidRuntimePermissions.Permission.Granted then
                canRecording = false
            end
        end
    end
    if canRecording then
        self.isRecording = true
        ---@type GME.QAVContext
        -- local context = self:GetVoiceEngine()
        -- context:GetPttCtrl():StartRecording(filePath)
    else
        ---没有权限的情况下
        GameUtils.Toast(localize('发语音消息需要录音权限'))
        if KTool.UNITY_ANDROID() then
            local AndroidRuntimePermissions = CS.AndroidRuntimePermissions
            AndroidRuntimePermissions.OpenSettings()
        end
    end
end

