function Social:StopTcp(isQuit)
    self.isQuit = checkBool(isQuit)
    --self.systemData = {} ---系统消息数据
    self.recruitData = {}
    self.recruitClubData = {}
    self.requests = {}
    self.clubData = {}
    local instance = self:GetSocialRelayGameObject()
    if instance then
        ---@type Engine.Network.KLobbyClientEx
        local lobbyClient = KTool.GetComponent(instance, typeof(KLobbyClientEx))
        if not lobbyClient then
            return
        end
        if lobbyClient.client then
            lobbyClient.client.packetHandlers:Clear()
        end
        self.preClientTime = lobbyClient.clientTime
        self.playerStartTime = self.preClientTime
        lobbyClient:DisconnectNow()
        lobbyClient:Disconnect()
    end
end
function Social:TcpLog(logType, logBody, packetId)
    if not Config.DEBUG then
        return
    end
    if logType == LOG_TYPE.SEND or logType == LOG_TYPE.TAKE then
        if IgnoreLogMap[checkInt(packetId)] then
            return
        end

        local logTitle = string.format('%s', packetId)
        local logDetail = ''
        if type(logBody) == 'table' then
            logDetail = table.toString(logBody, '')
        else
            logTitle = string.format('%s : %s', logTitle, checkString(logBody))
        end

        if logType == LOG_TYPE.SEND then
            print(string.format("<color=#FF99CC>[CHAT_TCP_SEND] %s</color>%s", logTitle, logDetail))
        else
            print(string.format("<color=#FFCC33>[CHAT_TCP_TAKE] %s</color>%s", logTitle, logDetail))
        end
    else
        print(string.format("<color=#FF9933>[CHAT_TCP_INFO] %s</color> %s", logBody, tostring(packetId)))
    end
end

function Social:InitLobbyClient(instance)
    ---@type Engine.Network.KLobbyClientEx
    local lobbyClient = KTool.GetOrAddComponent(instance, typeof(KLobbyClientEx))
    lobbyClient.PingDeltaTime = PING_TIME
    local lobbyClientType = lobbyClient:GetType()
    self.isNewLobbyApi = false
    if lobbyClientType:GetProperty("IsNewApiVersion") then
        self.isNewLobbyApi = true
    end
    if self.isNewLobbyApi then
        lobbyClient.TryTimes = 17280
    else
        KLobbyClientEx.TryTimes = 17280
    end

    if Config.DEBUG then
        local tcpProtocolType = lobbyClient.client.protocol:GetType()
        if not isNull(tcpProtocolType:GetProperty("OnSendLog")) then
            lobbyClient.client.protocol.OnSendLog = function(packetId, packetMsg)
                self:TcpLog(LOG_TYPE.SEND, packetMsg, packetId)
            end
        end
        if not isNull(tcpProtocolType:GetProperty("OnTakeLog")) then
            lobbyClient.client.protocol.OnTakeLog = function(packetId, packetMsg)
                self:TcpLog(LOG_TYPE.TAKE, packetMsg, packetId)
            end
        end
        if not isNull(tcpProtocolType:GetProperty("OnInfoLog")) then
            lobbyClient.client.protocol.OnInfoLog = function(infoMsg)
                self:TcpLog(LOG_TYPE.INFO, infoMsg)
            end
        end
    end
    self.handlerBackground = Events.AddListener(Constants.EventNames.ONAPP_TO_BG, function()
        lobbyClient.onPing = nil
        lobbyClient.onUpdate = nil
        self:StopTcp()
    end)
    self.handlerForeground = Events.AddListener(Constants.EventNames.ONAPP_TO_FG, function()
        if self.isQuit then
            return
        end
        if self.isNewLobbyApi then
            lobbyClient.canRetry = true
        else
            KLobbyClientEx.canRetry = true
        end
        self:ConnectLobbyServer(self.tcpHost)
    end)
    ---@type Engine.Lib.BehaviourAction
    local behaviorAction = KTool.GetOrAddComponent(instance, typeof(BehaviourAction))
    local EVT_ONAPP_TO_BG = Constants.EventNames.ONAPP_TO_BG
    local EVT_ONAPP_TO_FG = Constants.EventNames.ONAPP_TO_FG
    behaviorAction.OnDestroyAction = function()
        ----对象结束后删除注册的回调相关的方法
        self:OnUnRegisterEventCallback()
    end
    behaviorAction.OnDisableAction = function()
        print("====>>ondisabled")
        if self.isNewLobbyApi then
            lobbyClient.canRetry = false
        else
            KLobbyClientEx.canRetry = false
        end
        Events.RemoveListener(EVT_ONAPP_TO_BG, self.handlerBackground)
        Events.RemoveListener(EVT_ONAPP_TO_FG, self.handlerForeground)
        Events.RemoveListener(Constants.EventNames.OVERSEA_CHAT_HEARTBEAT, self.heartbeatEvent)
        --- stop
        self:StopTcp()
        lobbyClient.onConnect = nil
        lobbyClient.onDisconnect = nil
        lobbyClient.onPing = nil
        lobbyClient.onError = nil
        lobbyClient.onUpdate = nil
        self:CloseTimer()
        self.handlerBackground = nil
        self.handlerForeground = nil
        self.heartbeatEvent = nil
    end
    xTry(function()
        if (KTool.UNITY_ANDROID() or KTool.UNITY_IOS()) then
            local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            if not isNull(playerComp) then
                ---@type PlayerDojo
                local playerDojo = playerComp.playerDojo
                local resourceUrl = playerDojo.downloadResourceUrl
                -- resourceUrl = 'https://eater-ios-update.fantanggame.com/cat_hw_beta/android/patches/3.0.2403271718.2/resources/download.txt'
                if not string.isEmpty(resourceUrl) and string.find(resourceUrl, "http") then
                    resourceUrl = string.gsub(string.trim(resourceUrl), 'download.txt', '')
                    local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductSplitPath)
                    --@type BatchSyncer
                    local batchSyncer = BatchSyncer(resourceUrl, "download.txt", vendorPath, vendorPath, true)
                    local batchSyncerType = batchSyncer:GetType()
                    local property = batchSyncerType:GetProperty("IsReady")
                    if isNotNull(property) then
                        ---新的api的逻辑
                        batchSyncer.IsAutoDownload = false --自动下载的逻辑
                        batchSyncer.isStart = false
                        self.batchSyncer = batchSyncer
                        -- 重复下载时会被打断，导致下载不完的补丁
                        local property = batchSyncerType:GetProperty("IsRedownload")
                        if isNull(property) then
                            batchSyncer:SetCustomParserCallback(Bind(self, self.ProcessFileList))
                        end
                        batchSyncer:SetBeforeCallback(function(b)
                            ----下载的列表更新完成时，如果出异常这个方法不会走，不下载音频
                            ---添加是否下载第6章以资源的代码逻辑
                            xTry(function()
                                local startDownloaded = CS.Engine.Tools.PlayerPrefsUtility.GetEncryptedString("AUDIO_DOWNLOAD", '0')
                                if startDownloaded == '1' then
                                    if not batchSyncer:IsSuccess() then
                                        ---第7章开始
                                        batchSyncer.isStart = true
                                        batchSyncer:StartDownload() ---到达第7章，并且存在未下载完的音频资源，开始下载
                                        self.batchStarting = true
                                    else
                                        batchSyncer.IsFinish = true
                                    end
                                end
                            end)
                        end)
                        batchSyncer:Start()
                    else
                        batchSyncer = nil
                    end
                end
            end
        end
    end)
end

function Social:AddSystemMessage(data)
    table.insert(self.systemData, data)
    if #self.systemData > ChatConstants.MaxSystemMsgCount then
        table.remove(self.systemData, 1)
    end

    local switch = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 51).num
    if checkInt(switch) == 1 then
        local previewData = {
            channel = ChatConstants.Channels.System,
            text = self:ConvertSystemMessage(data),
            data = data,
        }
        self:InsertPreviewMessage(previewData)
    end
    
    if Events.HasListener(ChatConstants.EventNames.NEW_SYSTEM_MESSAGE) then
        Events.Broadcast(ChatConstants.EventNames.NEW_SYSTEM_MESSAGE, data)
    end
end

---转换系统消息
function Social:ConvertSystemMessage(data)
    local systemType = checkInt(data.systemType)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6089, "ChatSystemVo", systemType)
    if not vo then
        return ''
    end

    local txt = vo.txt
    local name = data.playerName or data.name or ''
    name = string.gsub(name, "%%", "")
    txt = string.gsub(txt, "_name_", name)
    if systemType == ChatConstants.ChatSystemMsgType.GACHAPON then
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(data.goodsId)
        if cardVo then
            txt = string.gsub(txt, "_id_", cardVo.name)
        end
    elseif systemType == ChatConstants.ChatSystemMsgType.GACHAPON_CATBALL then
        local catBallVo = CatBallUtils.GetCatBallVo(data.goodsId)
        if catBallVo then
            txt = string.gsub(txt, "_id_", catBallVo.name)
        end
    elseif systemType == ChatConstants.ChatSystemMsgType.ASYNC_PVP_RANK_DOWN then
        txt = string.gsub(txt, "_NUM_", data.playerRank)
    elseif systemType == ChatConstants.ChatSystemMsgType.ASYNC_PVP_SINGLE_RANK_DOWN then
        txt = string.gsub(txt, "_NUM_", data.playerRank)
    else
        txt = string.gsub(txt, "_NUM_", data.num or '')
    end
    return txt
end

function Social:GetNewMessageByPlayerId(playerId)
    local dbPath = DB_PATH
    local data = {}
    if File.Exists(dbPath) then
        local db = sqlite3.open(dbPath)
        xTry(function()
            if db and db:isopen() then
                local sql = string.format('select playerId, newMessage, lastReceiveTime, hasNewMessage, lastReadTime from message_remind2 where playerId = %d and myPlayerId = %d',
                        checkNumber(playerId),
                        checkNumber(self.playerId)
                )
                for row in db:nrows(sql) do
                    data = row
                end
                db:close()
            end
        end, function()
            db:close()
        end)
    end
    return checkTable(data)
end

---@param senderPlayerId number
---@return table<string, table>
function Social:GetUnreadMsgDataByPlayerId(senderPlayerId)
    local playerId = checkNumber(self.playerId)
    local dbPath = DB_PATH
    local dataMap = {}
    if File.Exists(dbPath) then
        local db = sqlite3.open(dbPath)
        xTry(function()
            if db and db:isopen() then
                local sql = string.format('select playerId, newMessage, lastReceiveTime, hasNewMessage, lastReadTime from message_remind2 where myPlayerId = %d',
                        playerId
                )
                if senderPlayerId then
                    sql = string.format('select playerId, newMessage, lastReceiveTime, hasNewMessage, lastReadTime from message_remind2 where playerId = %d and myPlayerId = %d',
                            checkNumber(senderPlayerId), playerId
                    )
                end
                for row in db:nrows(sql) do
                    if checkNumber(row.hasNewMessage) == 1 then
                        dataMap[tostring(row.playerId)] = row
                    end
                end
                db:close()
            end
        end, function()
            db:close()
        end)
    end
    return dataMap
end

---是否有某人的未读消息
---@param senderPlayerId number
function Social:IsHaveUnreadMsgByPlayerId(senderPlayerId)
    local hasUnreadMsg = false
    local friendComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.FriendComponent)
    if friendComp then
        for _, v in pairs(self:GetUnreadMsgDataByPlayerId(senderPlayerId)) do
            if friendComp:IsFriend(v.playerId) then
                hasUnreadMsg = true
                break
            end
        end
    end
    return hasUnreadMsg
end

function Social:ReadUnreadMessage(playerId)
    local dbPath = DB_PATH
    local insertId = 0
    if File.Exists(dbPath) then
        local newMsg = self:GetNewMessageByPlayerId(playerId)
        if newMsg and next(newMsg) ~= nil then
            local db = sqlite3.open(dbPath)
            xTry(function()
                if db and db:isopen() then
                    -- 判断此玩家有没有消息数据
                    local sql = nil
                    sql = string.format([[
                    update message_remind2 set lastReadTime = %d, hasNewMessage = %d where playerId = %d and myPlayerId = %d;
                ]],
                            checkInt(os.time()),
                            0,
                            checkInt(playerId),
                            checkInt(self.playerId)
                    )
                    --数据库打开后进行数据读取
                    db:exec('begin;')
                    db:exec(sql)
                    db:exec('commit;')
                    db:exec('end;')
                    -- pstmt:finalize()
                    insertId = db:last_insert_rowid()
                    -- print('-----------', insertId)
                    db:close()
                end
            end, function()
                db:close()
            end)
        end
    end

    self:UpdatePrivateChatRedPoint()
    return insertId
end

---UpdateUnReadMessage
---  {
----    playerId int 玩家Id
----    newMessage string 最新信息
----    lastReceiveTime int 接受最新信息时间
----    lastReadTime int 查看最新信息时间
----    hasNewMessage bool 是否有最新信息
-----}
---@param params table
function Social:UpdateUnReadMessage(params)
    if type(params) ~= 'table' then
        return
    end
    local dbPath = DB_PATH
    local insertId = 0
    if File.Exists(dbPath) then
        local db = sqlite3.open(dbPath)
        xTry(function()
            if db and db:isopen() then
                -- 判断此玩家有没有消息数据
                local sql = nil
                local temp = self:GetNewMessageByPlayerId(params.playerId)
                if temp and next(temp) ~= nil then
                    sql = string.format([[
                    update message_remind2 set newMessage = '%s', lastReceiveTime = %d, hasNewMessage = %d where playerId = %d and myPlayerId = %d;
                ]],
                            tostring(params.newMessage),
                            checkNumber(params.lastReceiveTime),
                            checkNumber(params.hasNewMessage),
                            checkNumber(params.playerId),
                            checkNumber(self.playerId)
                    )
                else
                    sql = string.format([[
                    insert into message_remind2 (playerId, newMessage, lastReceiveTime, lastReadTime, hasNewMessage, myPlayerId) values (%d, '%s', %d, 0, %d, %d);
                ]],
                            checkNumber(params.playerId),
                            tostring(params.newMessage),
                            checkNumber(params.lastReceiveTime),
                            checkNumber(params.hasNewMessage),
                            checkNumber(self.playerId)
                    )
                end
                --数据库打开后进行数据读取
                db:exec('begin;')
                db:exec(sql)
                db:exec('commit;')
                db:exec('end;')
                insertId = db:last_insert_rowid()
                -- print('-----------', insertId)
                db:close()
            end
        end, function()
            db:close()
        end)
    end
    return insertId

end

---ConnectLobbyServer
---connect to the chat server
---@param tcpHost string
function Social:ConnectLobbyServer(tcpHost)
    if string.isEmpty(tcpHost) then
        return
    end
    self.takePingTime = KLobbyClientEx.clientTime
    self.tcpHost = checkString(tcpHost)
    local instance = self:GetSocialRelayGameObject()
    if instance then
        ---@type Engine.Network.KLobbyClientEx
        local lobbyClient = KTool.GetComponent(instance, typeof(KLobbyClientEx))
        lobbyClient.client.packetHandlers:Clear()
        self.preClientTime = lobbyClient.clientTime
        self.playerStartTime = self.preClientTime
        lobbyClient:SetPacketHandler(ChatConstants.Packets.Common_Msg, CommonPacketHandler(function(packetId, data)
            print('--->>', table.dump(data, false, 2))
            if checkNumber(data.errCode) ~= 0 then
                GameUtils.Toast(tostring(data.msg) .. "^_^")
            end
        end))
        lobbyClient:SetPacketHandler(ChatConstants.Packets.Receive_Private_Msg, CommonPacketHandler(function(packetId, data)
            local t = self.requests[tostring(ChatConstants.Packets.Send_Private_Msg)]
            local req
            if t and #t > 0 then
                req = table.remove(t, 1)
            end
            if checkNumber(data.errCode) ~= 0 then
                GameUtils.Toast(tostring(data.msg) .. "^_^")
            else
                ---将私聊消息写入到数据库中去
                local playerId = checkNumber(self.playerId)
                print('--->>', table.dump(data.data, false, 2))
                for i, v in pairs(data.data) do
                    ----发送者
                    local senderPlayer = checkNumber(v.friendId)
                    local receivePlayerId = 0
                    if senderPlayer == playerId then
                        ----发送人是自己,本地发送消息的确认的情况下
                        if req then
                            receivePlayerId = checkNumber(req.friendId)
                        end
                    else
                        receivePlayerId = playerId
                    end
                    -- 记录最近联系人
                    self:SetRecentContacts(senderPlayer == playerId and receivePlayerId or senderPlayer)
                    if senderPlayer > 0 and receivePlayerId > 0 then
                        self:InsertChatMsg({
                            sendPlayerId = senderPlayer,
                            sendPlayerName = "",
                            receivePlayerId = receivePlayerId,
                            receivePlayerName = "",
                            content = tostring(v.message),
                            sendTime = checkNumber(v.sendTime),
                            msgType = checkNumber(v.msgType)
                        })
                        ---修改某读消息数据
                        if senderPlayer ~= playerId then
                            ---自己发出去的消息不需要小红点，某读消息的逻辑
                            self:UpdateUnReadMessage({
                                playerId = senderPlayer,
                                newMessage = tostring(v.message),
                                lastReceiveTime = checkNumber(v.sendTime),
                                hasNewMessage = 1,
                            })
                        end
                    end
                end
                self:UpdatePrivateChatRedPoint()

                local lastData = data.data[#data.data]
                if checkInt(lastData.friendId) ~= checkInt(playerId) then

                    local previewData = {
                        channel = ChatConstants.Channels.Private,
                        text = tostring(lastData.message),
                        friendId = lastData.friendId,
                        name = lastData.name
                    }
                    self:InsertPreviewMessage(previewData)
                end

                Events.Broadcast(tostring(ChatConstants.Packets.Send_Private_Msg), { req = req, resp = data.data })
            end
        end))
        lobbyClient:SetPacketHandler(ChatConstants.Packets.Receive_System_Msg, CommonPacketHandler(function(packetId, data)
            print('system--->>', table.dump(data, false, 2))
            if checkNumber(data.errCode) ~= 0 then
                GameUtils.Toast(tostring(data.msg) .. "^_^")
            else
                self:AddSystemMessage(data.data.message)
            end
        end))
        lobbyClient:SetPacketHandler(ChatConstants.Packets.Receive_Recruit_Msg, CommonPacketHandler(Bind(self, self.ReceiveRecruitMsgHandler)))
        lobbyClient:SetPacketHandler(ChatConstants.Packets.Delete_Recruit_Msg, CommonPacketHandler(Bind(self, self.DeleteRecruitMsgHandler)))
        lobbyClient:SetPacketHandler(ChatConstants.Packets.Receive_Club_Recruit_Msg, CommonPacketHandler(Bind(self, self.ReceiveClubRecruitMsgHandler)))
        lobbyClient:SetPacketHandler(ChatConstants.Packets.Delete_Club_Recruit_Msg, CommonPacketHandler(Bind(self, self.DeleteClubRecruitMsgHandler)))

        lobbyClient:SetPacketHandler(ChatConstants.Packets.Receive_Group_Chat_Msg, CommonPacketHandler(Bind(self, self.ReceiveGroupChatMsgHandler)))
        lobbyClient:SetPacketHandler(ChatConstants.Packets.Enter_Room, CommonPacketHandler(Bind(self, self.EnterRoomHandler)))
        lobbyClient.onConnect = function(isSuccess, message)
            self:OnTcpConnectHandler(lobbyClient, isSuccess, message)
        end
        lobbyClient.onDisconnect = function()
            self:OnTcpDisconnectHandler(lobbyClient)
        end
        lobbyClient.onPing = function(ip, ping)
            self.takePingTime = KLobbyClientEx.clientTime
        end
        lobbyClient.onUpdate = function()
            local clientTime = KLobbyClientEx.clientTime
            if lobbyClient.isActive then
                if clientTime > (self.takePingTime + 12000) then
                    -- 先改成12s 等解决加载问题，未🔗重试
                    --if clientTime > (self.takePingTime + CheckTcpRetryTimeDelta) then  -- 等待2次ping的周期还未响应的话
                    -- 当 DisconnectHandler 时标记为 true，然后 KNManager.Update 会满足条件重连
                    -- 但是重连没成功，那么就不会执行 ConnectHandler 的标记回 false，
                    -- 所以太长时间连接未应答的话，这里重新标记为 false，防止 KNManager.Update 中的重连 和 这里的重连 同时生效而重复重连
                    if self.isNewLobbyApi then
                        lobbyClient.canRetry = false
                    else
                        KLobbyClientEx.canRetry = false
                    end
                    self.takePingTime = clientTime  -- 记录前一次的时间记录
                    self:StopTcp()
                    self:ConnectLobbyServer(self.tcpHost)
                end
            end
        end
        lobbyClient.onError = function(message)
            local errorMsg = checkString(message)
            local errorData = table.deserialize(errorMsg)
            if errorData then
                errorMsg = checkString(errorData.msg)
            end
            GameUtils.Toast(errorMsg .. " T⌓T tcp")
        end
        lobbyClient:Connect(checkString(tcpHost))
    end
end

---接收招募信息消息处理
function Social:ReceiveRecruitMsgHandler(packetId, data)
    if checkNumber(data.errCode) ~= 0 then
        GameUtils.Toast(tostring(data.msg) .. "^_^")
        return
    end

    local update = false
    for _, v in ipairs(self.recruitData) do
        if v.roomId == data.data.roomId then
            -- 更新数据
            v = data.data
            update = true
            break
        end
    end

    if not update then
        table.insert(self.recruitData, 1, data.data)
    end
    Events.Broadcast(ChatConstants.EventNames.NEW_RECRUIT_MESSAGE)
end

---接收招募信息消息处理
function Social:ReceiveClubRecruitMsgHandler(packetId, data)
    if checkNumber(data.errCode) ~= 0 then
        GameUtils.Toast(tostring(data.msg) .. "^_^")
        return
    end
    table.insert(self.recruitClubData, 1, data.data)
    Events.Broadcast(ChatConstants.EventNames.NEW_CLUB_RECRUIT_MESSAGE)
end

---删除招募消息处理
function Social:DeleteRecruitMsgHandler(packetId, data)
    if checkNumber(data.errCode) ~= 0 then
        GameUtils.Toast(tostring(data.msg) .. "^_^")
        return
    end

    for i, v in ipairs(checkTable(self.recruitData)) do
        if v.roomId == data.data.roomId then
            table.remove(self.recruitData, i)
            break
        end
    end
    Events.Broadcast(ChatConstants.EventNames.NEW_RECRUIT_MESSAGE)
end

---删除社团招募消息处理
function Social:DeleteClubRecruitMsgHandler(packetId, data)
    if checkNumber(data.errCode) ~= 0 then
        GameUtils.Toast(tostring(data.msg) .. "^_^")
        return
    end

    for i, v in ipairs(checkTable(self.recruitClubData)) do
        if v.roomId == data.data.roomId then
            table.remove(self.recruitClubData, i)
            break
        end
    end
    Events.Broadcast(ChatConstants.EventNames.NEW_CLUB_RECRUIT_MESSAGE)
end

---接收群聊消息
function Social:ReceiveGroupChatMsgHandler(packetId, data)
    local previewData = {
        text = data.data.message,
        name = data.data.name
    }
    if data.data.chatChannel == ChatConstants.ChatServerChannel.Fight then
        table.insert(self.teamData, data.data)
        self:MarkNewMessage(ChatConstants.ChatServerChannel.Fight)
        previewData.channel = ChatConstants.Channels.Fight
    elseif checkNumber(data.data.chatChannel) == ChatConstants.ChatServerChannel.Union then
        ----工会消息数据
        table.insert(self.clubData, data.data)
        --self:InsertGroupMsg(data.data)
        self:MarkNewMessage(ChatConstants.ChatServerChannel.Union)
        previewData.channel = ChatConstants.Channels.Union
    elseif checkNumber(data.data.chatChannel) == ChatConstants.ChatServerChannel.World then
        table.insert(self.worldData, data.data)
        self:InsertGroupMsg(data.data)
        if #self.worldData > ChatConstants.MaxWorldMsgCount then
            table.remove(self.worldData, 1)
        end
        self:MarkNewMessage(ChatConstants.ChatServerChannel.World)
        previewData.channel = ChatConstants.Channels.World
    elseif checkNumber(data.data.chatChannel) == ChatConstants.ChatServerChannel.CrossWorld then
        table.insert(self.crossWorldData, data.data)
        --self:InsertGroupMsg(data.data)
        if #self.crossWorldData > ChatConstants.MaxCrossWorldMsgCount then
            table.remove(self.crossWorldData, 1)
        end
        self:MarkNewMessage(ChatConstants.ChatServerChannel.CrossWorld)
        previewData.channel = ChatConstants.Channels.CrossWorld
    end
    self:InsertPreviewMessage(previewData)
    Events.Broadcast(ChatConstants.EventNames.NEW_GROUP_CHAT_MESSAGE, data.data)
end

---进入房间处理
function Social:EnterRoomHandler(packetId, data)
    if checkNumber(data.data.chatChannel) == ChatConstants.ChatServerChannel.Recruit then
        self.recruitData = checkTable(data.data.roomList)
    elseif checkNumber(data.data.chatChannel) == ChatConstants.ChatServerChannel.ClubHelp then
        self.recruitClubData = checkTable(data.data.recruitLog)
    elseif checkNumber(data.data.chatChannel) == ChatConstants.Channels.Union then
        ---工会消息数据
        print("--->>", table.dump(data.data, false, 2))
        self.clubData = checkTable(data.data.messageList)
    end
end

--- 发送tcp请求数据
---@param packetId number
---@param data table
---@param isRecord function
function Social:SendTcpData(packetId, data, isRecord)
    if isNull(isRecord) then
        isRecord = true
    end
    local instance = self:GetSocialRelayGameObject()
    if instance then
        ---@type Engine.Network.KLobbyClientEx
        local lobbyClient = KTool.GetComponent(instance, typeof(KLobbyClientEx))
        if not lobbyClient.isConnected then
            GameUtils.Toast(localize('网络未连接，数据发送失败'))
            return
        end
        if data and isRecord then
            if not self.requests[tostring(packetId)] then
                self.requests[tostring(packetId)] = {}
            end
            table.insert(self.requests[tostring(packetId)], data)
        end
        local commonData = table.deserialize(requestMeta:ToJson())
        CfUtils.AddAreaIdRequest(commonData)
        if isTable(data) then
            table.merge(commonData, data)
        end
        local writer = lobbyClient:BeginSend(packetId)
        KLobbyClientEx.WritePayloadString(writer, table.serialize(commonData))
        lobbyClient:EndSend()
    end
end

--- disconnect
---@param lobbyClient Engine.Network.KLobbyClientEx
function Social:OnTcpDisconnectHandler(lobbyClient)
    if self.isNewLobbyApi then
        if lobbyClient.TryTimes < 0 then
            lobbyClient.canRetry = false
            GameUtils.Toast(localize('重试3次连接都失败了')) --重试3次连接都失败了
        else
            lobbyClient.canRetry = true ---测试3次，每次连接后重置下这个值
        end
    else
        if KLobbyClientEx.TryTimes < 0 then
            KLobbyClientEx.canRetry = false
            GameUtils.Toast(localize('重试3次连接都失败了')) --重试3次连接都失败了
        else
            KLobbyClientEx.canRetry = true ---测试3次，每次连接后重置下这个值
        end
    end
end

--- 连接成功或者失败时
---@param lobbyClient Engine.Network.KLobbyClientEx
---@param isSuccess boolean
---@param message string
function Social:OnTcpConnectHandler(lobbyClient, isSuccess, message)
    if isSuccess then
        self.takePingTime = KLobbyClientEx.clientTime
        print('----->> Social connected')
        self:EnterSystemRoom()
        self:EnterRecruitRoom()
        self:EnterClubRecruitRoom()
        self:EnterWorldRoom()
        self:EnterCrossWorldRoom()
        if self.teamRoomId then
            self:EnterTeamRoom(self.teamRoomId)
        end
        ---注意系统频道房间
        if self.isNewLobbyApi then
            lobbyClient.canRetry = false
        else
            KLobbyClientEx.canRetry = false
        end
    else
        if self.isNewLobbyApi then
            lobbyClient.canRetry = true
        else
            KLobbyClientEx.canRetry = false
        end
    end
end
---GetLobbyClient
---@return Engine.Network.KLobbyClientEx
function Social:GetLobbyClient()
    local instance = self:GetSocialRelayGameObject()
    if instance then
        return KTool.GetComponent(typeof(KLobbyClientEx))
    end
end

---GetPrivateChatMsg
---查找与某个玩家之前的聊天记录
---@param fromId number
---@param toId number
function Social:GetPrivateChatMsg(fromId, toId)
    local dbPath = DB_PATH
    local data = {}
    if File.Exists(dbPath) then
        local db = sqlite3.open(dbPath)
        xTry(function()
            if db and db:isopen() then
                --数据库打开后进行数据读取
                -- -select * from Qmsg t where ((t.sendPlayerId = %d and t.receivePlayerId = %d) or (t.sendPlayerId = %d and t.receivePlayerId = %d)) --desc
                local sql = string.format('select * from Qmsg t where ((t.sendPlayerId = %d and t.receivePlayerId = %d) or (t.sendPlayerId = %d and t.receivePlayerId = %d)) order by sendTime ;',
                        checkNumber(fromId),
                        checkNumber(toId),
                        checkNumber(toId),
                        checkNumber(fromId)
                )
                for row in db:nrows(sql) do
                    table.insert(data, row)
                end
                db:close()
            end
        end, function()
            db:close()
        end)
    end
    table.sort(data, function(a, b)
        return checkNumber(a.sendTime) < checkNumber(b.sendTime)
    end)
    return data
end

function Social:DeleteChatMsg(id)
    local dbPath = DB_PATH
    if File.Exists(dbPath) then
        local db = sqlite3.open(dbPath)
        xTry(function()
            if db and db:isopen() then
                --数据库打开后进行数据读取
                local sql = string.format('delete from Qmsg where id = %d;', checkNumber(id))
                if db:exec(sql) == sqlite3.OK then
                    --删除成功了
                    isOk = true
                end
                db:close()
            end
        end, function()
            db:close()
        end)
    end
    return isOk, id
end

