---初始化系统消息倒计时
function Social:InitialSystemMsgCountdown()
    local systemMsgCD = {}
    local syncPvpOpen = CfUtils.GetCfVo(AutoIds.IdSetting2560, 'LadderParameterVo', 2)
    systemMsgCD[ChatConstants.ChatSystemMsgType.SYNC_PVP_OPEN] = self:CalculateSystemMsgLeftTime(ChatConstants.ChatSystemMsgType.SYNC_PVP_OPEN, syncPvpOpen.num)
    local syncPvpClose = CfUtils.GetCfVo(AutoIds.IdSetting2560, 'LadderParameterVo', 3)
    systemMsgCD[ChatConstants.ChatSystemMsgType.SYNC_PVP_CLOSE] = self:CalculateSystemMsgLeftTime(ChatConstants.ChatSystemMsgType.SYNC_PVP_CLOSE, syncPvpClose.num)
    local asyncPvpSingleClose = CfUtils.GetCfVo(AutoIds.IdSetting4026, 'LadderParameterVo', 17)
    systemMsgCD[ChatConstants.ChatSystemMsgType.ASYNC_PVP_SINGLE_CLOSE] = self:CalculateSystemMsgLeftTime(ChatConstants.ChatSystemMsgType.ASYNC_PVP_SINGLE_CLOSE, asyncPvpSingleClose.num)
    local asyncPvpClose = CfUtils.GetCfVo(AutoIds.IdSetting4021, 'LadderParameterVo', 17)
    systemMsgCD[ChatConstants.ChatSystemMsgType.ASYNC_PVP_CLOSE] = self:CalculateSystemMsgLeftTime(ChatConstants.ChatSystemMsgType.ASYNC_PVP_CLOSE, asyncPvpClose.num)
    systemMsgCD[ChatConstants.ChatSystemMsgType.WORLD_BOSS_OPEN] = self:CalculateSystemMsgLeftTime(ChatConstants.ChatSystemMsgType.WORLD_BOSS_OPEN, "05:00")
    systemMsgCD[ChatConstants.ChatSystemMsgType.WORLD_BOSS_CLOSE] = self:CalculateSystemMsgLeftTime(ChatConstants.ChatSystemMsgType.WORLD_BOSS_CLOSE, "23:59")
    self.systemMsgCD = systemMsgCD
end

---计算系统消息剩余时间
function Social:CalculateSystemMsgLeftTime(msgType, timeStr)
    local systemMsgVo = CfUtils.GetCf(AutoIds.IdSetting6089, "ChatSystemVo")
    local params = systemMsgVo:Get(msgType)
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local t = {}
    if not isNull(playerComp) then
        ---@type PlayerDojo
        local playerDojo = playerComp.playerDojo
        local serverTime = playerDojo:GetServerTime()
        local serverTimezone = playerDojo:GetServerTimezone()
        local clientTimezone = playerDojo:GetClientTimezone()
        local timeStamp = serverTime + serverTimezone
        local timeStrList = string.split(timeStr, ";")
        for _, str in ipairs(timeStrList) do
            local tmp = {}
            local pattern = "(%d+):(%d+)"
            local hour, min = str:match(pattern)
            for i, v in ipairs(checkTable(params.num)) do
                local date = os.date("!*t", timeStamp)
                date.hour = hour
                date.min = checkInt(min) - v
                date.sec = 0
                local targetTS = os.time(date) - clientTimezone + serverTimezone * 2
                if targetTS < timeStamp then
                    targetTS = targetTS + 86400
                end
                --local date1 = os.date("!*t", targetTS)
                tmp[tostring(v)] = targetTS - timeStamp
            end
            table.insert(t, tmp)
        end
    end
    return t
end

function Social:SendSystemMsg()
    -- 弃用
    --for _, v in ipairs(TimerSystemMsgType) do
    --    local num = self:CheckTimeByChatSystemMsgType(v)
    --    if num then
    --        self:AddSystemMessage({ systemType = v, num = num })
    --    end
    --end
    for msgType, times in pairs(self.systemMsgCD) do
        for i, v in ipairs(checkTable(times)) do
            for num, time in pairs(checkTable(v)) do
                if time <= 0 then
                    self:AddSystemMessage({ systemType = msgType, num = num })
                    self.systemMsgCD[msgType][i][num] = 86400
                else
                    self.systemMsgCD[msgType][i][num] = time - 1
                end
            end
        end
    end
end

--- 弃用
function Social:CheckTimeByChatSystemMsgType(msgType)
    local systemMsgVo = CfUtils.GetCf(AutoIds.IdSetting6089, "ChatSystemVo")
    local vo

    if msgType == ChatConstants.ChatSystemMsgType.SYNC_PVP_OPEN then
        vo = CfUtils.GetCfVo(AutoIds.IdSetting2560, 'LadderParameterVo', 2)
    elseif msgType == ChatConstants.ChatSystemMsgType.SYNC_PVP_CLOSE then
        vo = CfUtils.GetCfVo(AutoIds.IdSetting2560, 'LadderParameterVo', 3)
    elseif msgType == ChatConstants.ChatSystemMsgType.ASYNC_PVP_SINGLE_CLOSE then
        vo = CfUtils.GetCfVo(AutoIds.IdSetting4026, 'LadderParameterVo', 17)
    elseif msgType == ChatConstants.ChatSystemMsgType.ASYNC_PVP_CLOSE then
        vo = CfUtils.GetCfVo(AutoIds.IdSetting4021, 'LadderParameterVo', 17)
    elseif msgType == ChatConstants.ChatSystemMsgType.WORLD_BOSS_OPEN then
        -- 世界boss排期表里是一天一配置，不知道怎么读，先写死算了
        vo = { num = "05:00" }
    elseif msgType == ChatConstants.ChatSystemMsgType.WORLD_BOSS_CLOSE then
        -- 同上
        vo = { num = "23:59" }
    end
    local pattern = "(%d+):(%d+)"
    local hour, min = vo.num:match(pattern)
    local params = systemMsgVo:Get(msgType)
    local num = self:CheckServerTime(hour, min, params)
    return num
end

function Social:CheckServerTime(hour, min, params)
    if not params then
        return
    end

    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if not isNull(playerComp) then
        ---@type PlayerDojo
        local playerDojo = playerComp.playerDojo
        local serverTime = playerDojo:GetServerTime()
        local serverTimezone = playerDojo:GetServerTimezone()
        for i, v in ipairs(checkTable(params.num)) do
            local date = os.date("!*t", serverTime + serverTimezone)
            local minT = checkInt(min) - checkInt(v)
            local hourT = checkInt(hour)
            if minT < 0 then
                minT = 60 + minT
                hourT = hourT - 1
                if hourT < 0 then
                    hourT = hourT + 24
                end
            end
            if date.sec == 0 and date.hour == hourT and date.min == minT then
                return v
            end
        end
    end
end

