function Social:InsertGroupMsg(params)
    self:CheckGroupMsgNum(params.chatChannel)
    if type(params) ~= 'table' then
        return
    end
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerId = playerComp.playerDojo.playerId
    local sql = string.format(
            [[
                insert into oversea_group_msg(userId, playerId, name, level,
                avatar, avatarFrame, message, sendTime, chatChannel, msgType, exParam1
                ) values (%d, %d, '%s', %d, %d, %d, '%s', %d, %d, %d, %d);
            ]],
            checkNumber(playerId),
            checkNumber(params.playerId),
            string.gsub(params.name, '\'', '\'\'') or '',
            checkNumber(params.level),
            checkNumber(params.avatar),
            checkNumber(params.avatarFrame),
            string.gsub(params.message, '\'', '\'\'') or '',
            checkNumber(params.sendTime),
