---检查群组消息数量, 最大为20条
function Social:CheckGroupMsgNum(channel)

    self:OpenDB(function(db)
        local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local playerId = playerComp.playerDojo.playerId
        local sql = string.format(
                [[
                    SELECT count(*) size FROM oversea_group_msg WHERE userId = %d AND chatChannel = %d AND exParam1 = %d
                ]],
                checkNumber(playerId),
                checkNumber(channel),
                checkNumber(requestMeta.serverId)
        )
        for row in db:nrows(sql) do
            if row.size >= ChatConstants.STORE_GROUP_MSG_MAX then
                local selSql = string.format(
                        [[
                            SELECT id FROM oversea_group_msg WHERE userId = %d AND chatChannel = %d AND exParam1 = %d ORDER BY sendTime DESC LIMIT 10 OFFSET %d
                        ]],
                        checkNumber(playerId),
                        checkNumber(channel),
                        checkNumber(requestMeta.serverId),
                        ChatConstants.STORE_GROUP_MSG_MAX - 1
                )
                for row2 in db:nrows(selSql) do
                    local delSql = string.format(
                            [[
                                DELETE FROM oversea_group_msg WHERE id = %d
                            ]],
                            row2.id
                    )
                    db:exec(delSql)
                end
            end
        end
    end)
end

---开启数据库
function Social:OpenDB(func)
    if isNull(func) then
        return
    end

    local dbPath = DB_PATH
    if File.Exists(dbPath) then
        local db = sqlite3.open(dbPath)
        xTry(function()
            if db and db:isopen() then
                --数据库打开后进行数据读取
                db:exec('begin;')
                func(db)
                db:exec('commit;')
                db:close()
            end
        end, function()
            db:close()
        end)
    end
end

---执行sql语句
function Social:ExecSql(sql)
    if isNull(sql) then
        return
    end

    self:OpenDB(function(db)
        db:exec(tostring(sql))
    end)
end

---设置最近联系人(存本地，最多存3个)
function Social:SetRecentContacts(friendId)
    local data = CfUtils.GetLocalData("RecentContactsList", '{}')
    data = table.deserialize(data)
    setmetatable(data, {})
    for i, v in ipairs(data) do
        if checkInt(v) == checkInt(friendId) then
            table.remove(data, i)
            break
        end
    end
    table.insert(data, 1, friendId)
    if #data > ChatConstants.STORE_RECENT_CONTACTS_MAX then
        for i = #data, ChatConstants.STORE_RECENT_CONTACTS_MAX + 1, -1 do
            table.remove(data)
        end
    end
    data = table.serialize(data)
    CfUtils.WriteLocalData("RecentContactsList", data)
end

