function Social:ProcessFileList(batchSyncer)
    local lineList = {}
    local path1 = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductSplitPath)
    local path = PathUtility.Combine(path1, 'download.txt.tmp')
    if File.Exists(path) then
        local streamReader = StreamReader(path)
        local line = streamReader:ReadLine()
        while not string.isEmpty(line) do
            line = string.trim(line)
            if not string.isEmpty(line) then
                table.insert(lineList, line)
            end
            line = streamReader:ReadLine()
        end
        streamReader:Close()
    end

    -- Process the list
    for _, line in ipairs(lineList) do
        local file
        local toDelete = false
        if line:sub(1, 1) == "-" then
            file = line:sub(2):match("^%s*(.-)%s*$")  -- trimStart '-' and trim
            toDelete = true
        else
            file = line:match("^%s*(.-)%s*$")  -- trim
        end

        local items = {}
        for item in file:gmatch("[^\t]+") do
            table.insert(items, item:match("^%s*(.-)%s*$"))  -- trim
        end

        local url = items[1]
        file = items[2]
        local hash = items[3]
        local size = tonumber(items[4])

        local fileUrl = string.endsWith(batchSyncer.UrlPrefix, '/') and batchSyncer.UrlPrefix .. url or batchSyncer.UrlPrefix .. '/' .. url
        local savePath = PathUtility.Combine(batchSyncer.SaveDir, file)

        if toDelete then
            if file == "*" then
                self:DeleteAllOthers(batchSyncer.SaveDir, batchSyncer.BatchFileName)
            else
                if File.Exists(savePath) then
                    File.Delete(savePath)
                end
            end
        else
            local already = false
            if File.Exists(savePath) then
                local fi = FileInfo(savePath)
                if Mathf.Abs(fi.Length - size) <= 0.0001 then
                    already = true
                end
            end

            if not already then
                local filePuller = FileSyncer(fileUrl, savePath, batchSyncer.MetaDirectory, hash)
                filePuller.Size = size
                batchSyncer.Syncers:Add(filePuller)
                batchSyncer.Tasks:Enqueue(filePuller)
            end
        end
    end
end

function Social:DeleteAllOther(SaveDir, BatchFileName)
    if Directory.Exists(SaveDir) then
        local files = Directory.GetFiles(SaveDir, "*", SearchOption.AllDirectories)
        local count = files.Count
        for i = 0, count - 1, 1 do
            local filePath = files[i]
            if Path.GetFileName(filePath) ~= BatchFileName then
                File.Delete(filePath)
            end
        end
    end
end

